import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2018-May-03 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-May-03 :: Ceph Performance Weekly","date":"2018-05-03T00:00:00.000Z","updated":"2018-05-04T00:00:00.000Z","tags":["Ceph","BlueFS","Cache Auto","Tuning","Performance Optimization","Logging"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-May-03_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-May-03_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),r={name:"posts/2018/2018-May-03_-_-_Ceph_Performance_Weekly.md"};function n(s,l,p,a,_,g){return t(),i("div",null,[...l[0]||(l[0]=[o("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2018年5月3日</p><p><strong>参会人员</strong>： 主要讨论了缓存自动调优和日志记录等议题，具体参会人员未提及。</p><p><strong>会议主题</strong>： Ceph社区更新、关键议题讨论、行动计划</p><p><strong>关键细节</strong>：</p><ul><li><strong>社区更新</strong>： <ul><li>Peter提交了一个新的PR，旨在减少在BlueFS中执行日志记录时的无缓冲树构建，这可能对性能产生积极影响。</li><li>Josh关闭了一些与CBT相关的PR，Neha正在努力修复这些问题。</li><li>Redick关闭了一些旧的PR，旨在改进与NSS相关的功能，并可能转向OpenSSL。</li><li>Atom提交了两个PR，一个关于限制页面错误，另一个关于哈希。</li></ul></li><li><strong>缓存自动调优</strong>： <ul><li>讨论了在BlueFS中启用缓冲写入的利弊，以及自动调优缓存的不同行为。</li><li>发现缓冲写入在某些情况下可能会降低性能，但可能在其他情况下有所帮助。</li><li>目前正在收集更多数据以评估自动调优的效果。</li></ul></li><li><strong>日志记录</strong>： <ul><li>讨论了当前日志记录的性能影响，以及未来可能采用的新日志记录方法。</li></ul></li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li>缓存自动调优的效果和最佳实践。</li><li>在BlueFS中启用缓冲写入的利弊。</li><li>日志记录的性能影响和改进方法。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>继续收集缓存自动调优的数据，并评估其效果。</li><li>进一步研究在BlueFS中启用缓冲写入的最佳实践。</li><li>观察和讨论日志记录的性能影响和改进方法。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Josh和Neha将继续修复CBT相关的问题。</li><li>Redick将继续改进与NSS相关的功能。</li><li>Atom将继续研究限制页面错误和哈希的问题。</li><li>社区成员将关注缓存自动调优和日志记录的讨论，并提供反馈。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到的关键术语包括：BlueFS、CBT、OSS、OpenSSL、页面错误、哈希等。</li><li>会议中提到的PR编号和作者未在纪要中列出。</li></ul>",14)])])}const S=e(r,[["render",n]]);export{c as __pageData,S as default};
